// Switch the LED on GPIO4 from a web page
#include <WiFi.h>
#include <WebServer.h>

const char* SSID = "{{p:ssid}}";
const char* PASS = "robotics";             // the bench-lab network's password
const uint8_t LED_PIN = 4;
const uint8_t RGB_PIN = 38;

WebServer server(80);

void handleRoot() {
  server.send(200, "text/html", "<h1>ESP32-S3</h1><a href=\"/on\">LED on</a> <a href=\"/off\">LED off</a>");
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  WiFi.mode(WIFI_STA);                     // join a network as a station
  WiFi.begin(SSID, PASS);
  Serial.print("Connecting to ");
  Serial.println(SSID);
  while (WiFi.status() != WL_CONNECTED) {
    rgbLedWrite(RGB_PIN, 0, 0, 64);        // blue blink while connecting
    delay(250);
    rgbLedWrite(RGB_PIN, 0, 0, 0);
    delay(250);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Connected, IP ");
  Serial.println(WiFi.localIP().toString());
  rgbLedWrite(RGB_PIN, 0, 64, 0);          // green: on the network
  server.on("/", handleRoot);
  server.on("/on", []() {
    digitalWrite(LED_PIN, HIGH);
    server.send(200, "text/plain", "LED on");
    Serial.println("GET /on");
  });
  server.on("/off", []() {
    digitalWrite(LED_PIN, LOW);
    server.send(200, "text/plain", "LED off");
    Serial.println("GET /off");
  });
  server.begin();
}

void loop() {
  server.handleClient();                   // answer requests, never block here
}

